import * as React from 'react';
import { render, fireEvent, cleanup, screen } from '@testing-library/react';
import * as DropdownMenu from './dropdown-menu';
import { describe, it, afterEach, vi, expect } from 'vitest';

describe('given a DropdownMenu', () => {
  afterEach(cleanup);

  describe('given a stable ref on the Trigger', () => {
    it('should not re-invoke the ref when the menu opens and closes', () => {
      const handleRef = vi.fn();
      render(
        <DropdownMenu.Root>
          <DropdownMenu.Trigger asChild ref={handleRef}>
            <button type="button">menu</button>
          </DropdownMenu.Trigger>
          <DropdownMenu.Content>
            <DropdownMenu.Item>Item</DropdownMenu.Item>
          </DropdownMenu.Content>
        </DropdownMenu.Root>,
      );

      const trigger = screen.getByRole('button', { name: 'menu' });
      expect(handleRef).toHaveBeenCalledTimes(1);

      fireEvent.click(trigger);
      expect(handleRef).toHaveBeenCalledTimes(1);

      fireEvent.click(trigger);
      expect(handleRef).toHaveBeenCalledTimes(1);
    });
  });
});

