import * as React from 'react';
import { render, fireEvent, cleanup, screen } from '@testing-library/react';
import * as Menu from './menu';
import { describe, it, afterEach, vi, expect } from 'vitest';

describe('given a Menu', () => {
  afterEach(cleanup);

  describe('given a stable ref on a SubTrigger', () => {
    it('should not re-invoke the ref when the menu re-renders', () => {
      const handleRef = vi.fn();

      const App = () => {
        const [open, setOpen] = React.useState(false);
        const [, setTick] = React.useState(0);
        return (
          <>
            <button type="button" onClick={() => setTick((tick) => tick + 1)}>
              tick
            </button>
            <Menu.Root open={open} onOpenChange={setOpen}>
              <Menu.Trigger>menu</Menu.Trigger>
              <Menu.Content>
                <button type="button" onClick={() => setTick((tick) => tick + 1)}>
                  tick
                </button>
                <Menu.Sub>
                  <Menu.SubTrigger ref={handleRef}>Sub</Menu.SubTrigger>
                  <Menu.SubContent>
                    <Menu.Item>Item</Menu.Item>
                  </Menu.SubContent>
                </Menu.Sub>
              </Menu.Content>
            </Menu.Root>
          </>
        );
      };

      render(<App />);

      fireEvent.click(screen.getAllByRole('button', { name: 'menu' })[0]);
      expect(handleRef).toHaveBeenCalledTimes(1);

      // Re-render the whole tree from the inside of the menu, so the
      // outside dismiss does not interfere.
      fireEvent.click(screen.getAllByRole('button', { name: 'tick' })[1]);
      expect(handleRef).toHaveBeenCalledTimes(1);

      fireEvent.click(screen.getAllByRole('button', { name: 'tick' })[1]);
      expect(handleRef).toHaveBeenCalledTimes(1);
    });
  });
});

