import * as React from 'react';
import { render, fireEvent, cleanup, screen } from '@testing-library/react';
import * as NavigationMenu from './navigation-menu';
import { describe, it, afterEach, vi, expect } from 'vitest';

describe('given a NavigationMenu', () => {
  afterEach(cleanup);

  it('should not re-invoke a content ref when the active value changes', () => {
    const itemRef = vi.fn();

    const App = () => {
      const [value, setValue] = React.useState('');
      return (
        <>
          <button type="button" onClick={() => setValue('one')}>
            select one
          </button>
          <button type="button" onClick={() => setValue('two')}>
            select two
          </button>
          <NavigationMenu.Root value={value} onValueChange={setValue}>
            <NavigationMenu.List>
              <NavigationMenu.Item value="one">
                <NavigationMenu.Trigger>One</NavigationMenu.Trigger>
              </NavigationMenu.Item>
              <NavigationMenu.Item value="two">
                <NavigationMenu.Trigger>Two</NavigationMenu.Trigger>
              </NavigationMenu.Item>
              <NavigationMenu.Item value="three">
                <NavigationMenu.Trigger>Three</NavigationMenu.Trigger>
              </NavigationMenu.Item>
            </NavigationMenu.List>
            <NavigationMenu.Viewport>
              <NavigationMenu.Content value="one">One</NavigationMenu.Content>
              <NavigationMenu.Content value="two">Two</NavigationMenu.Content>
              <NavigationMenu.Content value="three" forceMount ref={itemRef}>
                Three
              </NavigationMenu.Content>
            </NavigationMenu.Viewport>
          </NavigationMenu.Root>
        </>
      );
    };

    render(<App />);

    // The viewport mounts and the force-mounted content attaches its ref once.
    fireEvent.click(screen.getByRole('button', { name: 'select one' }));
    expect(itemRef).toHaveBeenCalledTimes(1);

    // Changing the active value re-renders the viewport; the ref of a
    // content item that never becomes active must not be re-invoked.
    fireEvent.click(screen.getByRole('button', { name: 'select two' }));
    expect(itemRef).toHaveBeenCalledTimes(1);
  });
});

